const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const signature = headers['x-slack-signature'];
const timestamp = headers['x-slack-request-timestamp'];

// Read the raw request body (webhook "Raw Body" option stores it as binary "data")
let raw = '';
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  raw = buf.toString('utf8');
} catch (e) {
  raw = '';
}
// Fallback: reconstruct the form-encoded body from the parsed fields
if (!raw && item.json.body) {
  raw = Object.keys(item.json.body).map(k => k + '=' + encodeURIComponent(item.json.body[k])).join('&');
}

// Paste your Slack Signing Secret between the quotes to enable verification.
// (This instance blocks env-var access, so use this constant.)
let signingSecret = 'YOUR_SLACK_SIGNING_SECRET';
try {
  if (!signingSecret) signingSecret = $env.SLACK_SIGNING_SECRET || '';
} catch (e) {
  // env access disabled on this instance - fall back to the constant above
}

if (signingSecret) {
  if (!signature || !timestamp) {
    throw new Error('Rejected: missing Slack signature headers (401)');
  }
  // Replay protection: reject requests older than 5 minutes
  const now = Math.floor(Date.now() / 1000);
  if (Math.abs(now - Number(timestamp)) > 300) {
    throw new Error('Rejected: Slack request timestamp too old (401)');
  }
  const baseString = 'v0:' + timestamp + ':' + raw;
  const expected = 'v0=' + crypto.createHmac('sha256', signingSecret).update(baseString).digest('hex');
  const ok = signature.length === expected.length && crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(signature));
  if (!ok) {
    throw new Error('Rejected: invalid Slack signature (401)');
  }
} else {
  console.warn('SLACK_SIGNING_SECRET not configured - signature verification skipped');
}

// Rebuild the parsed body from the raw payload so downstream nodes keep working
const bodyObj = {};
raw.split('&').forEach(pair => {
  if (!pair) return;
  const idx = pair.indexOf('=');
  const k = idx === -1 ? pair : pair.slice(0, idx);
  const v = idx === -1 ? '' : pair.slice(idx + 1);
  bodyObj[decodeURIComponent(k)] = decodeURIComponent(v.split('+').join(' '));
});
return [{ json: { headers, body: bodyObj } }];

